import{_ as o,l as S,o as a,c as i,v as t,p as n,x as r,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"SSE 与服务器推送","description":"","frontmatter":{"title":"SSE 与服务器推送","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sse-server-push.md","filePath":"cs/sse-server-push.md","lastUpdated":1789023840000}'),E={name:"cs/sse-server-push.md"};function p(h,e,T,P,_,u){const s=S("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="sse-与服务器推送" tabindex="-1">SSE 与服务器推送 <a class="header-anchor" href="#sse-与服务器推送" aria-label="Permalink to &quot;SSE 与服务器推送&quot;">​</a></h1><div class="epigraph"><p>SSE 用一条永不结束的 HTTP 响应流文本事件；HTTP/2 服务器推送则预推缓存资源，对象不同，都常被误叫「推送」。</p><footer>—— 据 W3C Server-Sent Events；RFC 9113 服务器推送整理</footer></div><p><a href="/cs/websocket">WebSocket</a> 是双向帧。<a href="/cs/websocket">上一课</a> 对只读更新偏重。缺口是 <strong>SSE</strong> 与 <strong>H2 PUSH</strong> 对照：一个是事件流，一个是推资源。本课不把 gRPC 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票 ticker、通知：服务器 → 客户端即可。SSE：<code>text/event-stream</code>，chunked 或 H2 流上发 <code>data:</code> 行，浏览器自动重连并带 <code>Last-Event-ID</code>。仍是 HTTP 语义，过代理比 WS 容易。H2/H3 的 PUSH：服务器猜测下一资源推进缓存，实现与隐私问题导致浏览器削弱——不是 SSE 替代。</p><p>不要把 SSE 写成 WebSocket 的子集协议。</p><p><span class="marginnote">WHATWG/W3C SSE。H3 不用 H2 那种 PUSH，点名。本课不写 EventSource API 全集。</span></p><h3 id="单向事件流" tabindex="-1">单向事件流 <a class="header-anchor" href="#单向事件流" aria-label="Permalink to &quot;单向事件流&quot;">​</a></h3><p>持久 GET，自动重连带 Last-Event-ID。H2 PUSH 是资源预推，对象不同。代理缓冲会把实时变成批量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：轮询 / SSE / WS / H2 PUSH。画：GET 事件流 → 多 event 块。与 Cookie：同一请求会话。压缩：对事件流要小心缓冲延迟。</p>',11)),(a(),n(c,null,{default:r(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GET%5B%22GET%20event-stream%22%5D%20--%3E%20EV%5B%22data%20%E8%A1%8C%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20EV%20--%3E%20REC%5B%22Last-Event-ID%20%E9%87%8D%E8%BF%9E%22%5D%0A%20%20PUSH%5B%22H2%20PUSH%22%5D%20--%3E%20CACHE%5B%22%E5%A1%AB%E6%B5%8F%E8%A7%88%E5%99%A8%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反向代理要关缓冲，否则 SSE 变成批量。负载均衡空闲超时会拆流，要心跳注释行。HOL：H1 上 SSE 占一条持久连接。无线：重连风暴。与 QUIC 多流：可用专用流跑 SSE 风格。</p><p>H2 PUSH 与 CDN 预取后课相关，不是实时消息。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MQTT 的全部。REST 与 gRPC 是下一课。后课默认：SSE 是单向 HTTP 事件流；PUSH 是资源预推。</p><p>把所有实时都升级到 WS 会浪费。</p><p>上一课留下的缺口在本课收口；「SSE 与服务器推送」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/rest-grpc">REST 与 gRPC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SSE：持久 GET，文本事件，易过 HTTP 中间件。</li><li>H2 PUSH：资源，不是消息总线。</li><li>代理缓冲与超时是部署坑。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：W3C SSE；RFC 9113。</li></ul>',10))])}const f=o(E,[["render",p]]);export{m as __pageData,f as default};
